window.VO = [{"id":"n01","text":"You're the only witness to this crash.","at":0.24,"t0":0.12,"t1":1.865},{"id":"n02","text":"Watch closely.","at":4.17,"t0":2.085,"t1":3.04},{"id":"n03","text":"The driver doesn't stop.","at":10.38,"t0":5.19,"t1":6.635},{"id":"n04","text":"So you're all this man has.","at":13.87,"t0":6.935,"t1":8.32},{"id":"n05","text":"How fast was the rickshaw going when it smashed into the cart?","at":19.84,"t0":9.92,"t1":13.05},{"id":"n06","text":"And the broken glass: left of the cart, or right?","at":29.2,"t0":14.6,"t1":17.43},{"id":"n07","text":"There was no broken glass.","at":40.86,"t0":20.43,"t1":21.9},{"id":"n08","text":"Go back and look.","at":44.7,"t0":22.35,"t1":23.37},{"id":"n09","text":"He never asked if there was any.","at":48.94,"t0":24.47,"t1":26.23},{"id":"n10","text":"He asked where it was.","at":53.06,"t0":26.53,"t1":27.805},{"id":"n11","text":"And some of you could almost see it.","at":56.61,"t0":28.305,"t1":29.87},{"id":"n12","text":"Because your brain doesn't replay a memory.","at":60.34,"t0":30.17,"t1":32.3},{"id":"n13","text":"It rebuilds it, every time, with whatever it's just heard.","at":65.1,"t0":32.55,"t1":35.78},{"id":"n14","text":"Even one word can do it.","at":72.66,"t0":36.33,"t1":37.925},{"id":"n15","text":"In nineteen seventy-four, students whose question said smashed, not hit, were twice as likely, a week later, to remember broken glass.","at":76.45,"t0":38.225,"t1":46.18},{"id":"n16","text":"There wasn't any.","at":93.06,"t0":46.53,"t1":47.6},{"id":"n17","text":"That's why judges usually stop questions like his.","at":96.3,"t0":48.15,"t1":51.04},{"id":"n18","text":"Out here, nobody did.","at":102.68,"t0":51.34,"t1":52.69},{"id":"n19","text":"So if you picked a side, the police are now looking for broken glass.","at":106.18,"t0":53.09,"t1":56.9},{"id":"n20","text":"His glass is fine.","at":114.5,"t0":57.25,"t1":58.44},{"id":"n21","text":"Said there wasn't any? Good.","at":120.38,"t0":60.19,"t1":61.78},{"id":"n22","text":"What hit his windscreen?","at":124.36,"t0":62.18,"t1":63.51}];
